`timescale 1ns / 1ps
// =============================================================================
// ECG sample ROM (demo) — 8-bit samples, 1-cycle read latency
// =============================================================================
// Loads an 8-bit ECG sample segment from a hex file (generated by
// demo/ecg_convert.py) and serves it to the sample pacer.
//
// Synthesizable: a reg array + $readmemh infers RAM/LUTROM in Gowin and is
// fully supported in Questa. The read is REGISTERED -> exactly 1-cycle latency
// (rom_out = ROM[rom_addr] from the previous posedge). The pacer holds rom_addr
// stable for a whole inter-sample period, so the 1-cycle latency is absorbed
// trivially and no sample is lost.
//
// Ports: plain address/data; no reset (RAM contents come from the hex file).
// =============================================================================

module ecg_rom #(
    parameter ROM_WORDS = 2048,      // number of 8-bit samples
    parameter ROM_DW    = 8,         // sample width
    parameter ROM_HEX   = "demo_ecg_rom.hex"   // file, relative to sim cwd
) (
    input  wire             clk,
    input  wire [$clog2(ROM_WORDS)-1:0] rom_addr,
    output wire [ROM_DW-1:0] rom_out    // ROM[rom_addr @ previous posedge]
);

    localparam AW = $clog2(ROM_WORDS);

    // Inferred ROM/RAM array. $readmemh loads the hex file in simulation.
    // Gowin infers a RAMB or LUTROM from this array + registered read.
    reg [ROM_DW-1:0] rom [0:ROM_WORDS-1];

    // $readmemh loads the on-disk hex (ROM_WORDS words). No zero-init loop: a
    // 2048-iteration for trips Gowin's synthesis loop-limit (EX3934 "loop count
    // limit of 2000 exceeded"). The demo hex always has ROM_WORDS entries and
    // the RAM is read-only, so an unwritten slot would only be X in sim and is
    // never reachable in the demo.
    initial begin
        $readmemh(ROM_HEX, rom);
        $display("[ecg_rom] $readmemh(\"%s\"): loaded %0d words", ROM_HEX, ROM_WORDS);
    end

    // 1-cycle read latency.
    reg [ROM_DW-1:0] rom_out_r;
    always @(posedge clk)
        rom_out_r <= rom[rom_addr];
    assign rom_out = rom_out_r;

endmodule
